using System;
using System.Collections.Generic;
using UnityEngine;

namespace CrowdingAwareLOD
{
    [Serializable]
    public class CrowdingSceneVariantEntry
    {
        public string variantKey;
        public int fixationIndex;
        public float groupKeepRatioK;
        public CrowdingDecimationCondition condition;
        public GameObject sceneVariantRoot;
    }

    /// <summary>
    /// Runtime selector for precomputed Blender variants.
    /// Each variant root should contain the visual scene generated by Blender for one combination:
    /// K in {0.6, 0.3} x condition in {Uniform, WeightedCrowding} x fixation point.
    /// </summary>
    [DisallowMultipleComponent]
    public class CrowdingCombinationLODSelector : MonoBehaviour
    {
        [Header("Original scene visuals")]
        [Tooltip("Optional root for the non-decimated scene. It will be hidden when a precomputed variant is active.")]
        public GameObject originalSceneRoot;

        [Header("Current combination")]
        public int currentFixationIndex = 0;
        [Range(0.01f, 1f)] public float currentGroupKeepRatioK = 0.6f;
        public CrowdingDecimationCondition currentCondition = CrowdingDecimationCondition.WeightedCrowding;

        [Header("Precomputed Blender variants")]
        public List<CrowdingSceneVariantEntry> variants = new List<CrowdingSceneVariantEntry>();

        [Header("Behaviour")]
        public bool applyOnStart = true;
        public bool showOriginalWhenVariantMissing = true;
        public bool logChanges = true;

        public string CurrentVariantKey
        {
            get { return CrowdingVariantKey.Build(currentFixationIndex, currentGroupKeepRatioK, currentCondition); }
        }

        private void Start()
        {
            if (applyOnStart) ApplyCurrentCombination();
        }

        [ContextMenu("Crowding LOD/Apply Current Combination")]
        public void ApplyCurrentCombination()
        {
            ApplyCombination(currentFixationIndex, currentGroupKeepRatioK, currentCondition);
        }

        public void ApplyCombination(int fixationIndex, float groupKeepRatioK, CrowdingDecimationCondition condition)
        {
            currentFixationIndex = fixationIndex;
            currentGroupKeepRatioK = groupKeepRatioK;
            currentCondition = condition;

            string key = CurrentVariantKey;
            CrowdingSceneVariantEntry selected = FindVariant(key);

            for (int i = 0; i < variants.Count; i++)
            {
                if (variants[i] != null && variants[i].sceneVariantRoot != null)
                    variants[i].sceneVariantRoot.SetActive(selected != null && variants[i] == selected);
            }

            bool hasVariant = selected != null && selected.sceneVariantRoot != null;
            if (originalSceneRoot != null)
                originalSceneRoot.SetActive(!hasVariant && showOriginalWhenVariantMissing);

            if (logChanges)
            {
                if (hasVariant)
                    Debug.Log("CrowdingCombinationLODSelector: active variant = " + key);
                else
                    Debug.LogWarning("CrowdingCombinationLODSelector: variant not found for key " + key);
            }
        }

        public void ShowOriginalOnly()
        {
            for (int i = 0; i < variants.Count; i++)
            {
                if (variants[i] != null && variants[i].sceneVariantRoot != null)
                    variants[i].sceneVariantRoot.SetActive(false);
            }
            if (originalSceneRoot != null) originalSceneRoot.SetActive(true);
        }

        public CrowdingSceneVariantEntry FindVariant(string key)
        {
            for (int i = 0; i < variants.Count; i++)
            {
                CrowdingSceneVariantEntry entry = variants[i];
                if (entry == null) continue;
                if (entry.variantKey == key) return entry;
            }
            return null;
        }

        [ContextMenu("Crowding LOD/Refresh Variant Keys From Fields")]
        public void RefreshVariantKeysFromFields()
        {
            for (int i = 0; i < variants.Count; i++)
            {
                CrowdingSceneVariantEntry entry = variants[i];
                if (entry == null) continue;
                entry.variantKey = CrowdingVariantKey.Build(entry.fixationIndex, entry.groupKeepRatioK, entry.condition);
            }
        }

        [ContextMenu("Crowding LOD/Auto Populate Variants From Children")]
        public void AutoPopulateVariantsFromChildren()
        {
            variants.Clear();

            for (int i = 0; i < transform.childCount; i++)
            {
                Transform child = transform.GetChild(i);
                if (child == null) continue;

                string key = ExtractVariantKey(child.name);
                if (string.IsNullOrEmpty(key)) continue;

                CrowdingSceneVariantEntry entry = new CrowdingSceneVariantEntry();
                entry.variantKey = key;
                entry.sceneVariantRoot = child.gameObject;
                ParseVariantKey(key, out entry.fixationIndex, out entry.groupKeepRatioK, out entry.condition);
                variants.Add(entry);
            }

            if (logChanges)
                Debug.Log("CrowdingCombinationLODSelector: auto-populated variants from children = " + variants.Count);
        }

        private static string ExtractVariantKey(string name)
        {
            if (string.IsNullOrEmpty(name)) return string.Empty;

            int fIndex = name.IndexOf("F", StringComparison.Ordinal);
            while (fIndex >= 0 && fIndex < name.Length)
            {
                string candidate = name.Substring(fIndex);
                if (candidate.Length >= 17 && candidate.StartsWith("F", StringComparison.Ordinal) && candidate.Contains("_K") && (candidate.Contains("_weighted") || candidate.Contains("_uniform")))
                {
                    int end = candidate.IndexOf(" ", StringComparison.Ordinal);
                    if (end > 0) candidate = candidate.Substring(0, end);
                    return candidate;
                }
                fIndex = name.IndexOf("F", fIndex + 1, StringComparison.Ordinal);
            }

            return string.Empty;
        }

        private static void ParseVariantKey(string key, out int fixationIndex, out float k, out CrowdingDecimationCondition condition)
        {
            fixationIndex = 0;
            k = 1f;
            condition = CrowdingDecimationCondition.Uniform;

            try
            {
                // Expected: F00_K060_weighted
                string[] parts = key.Split('_');
                if (parts.Length >= 3)
                {
                    if (parts[0].Length >= 3) int.TryParse(parts[0].Substring(1), out fixationIndex);
                    if (parts[1].Length >= 4)
                    {
                        int k100;
                        if (int.TryParse(parts[1].Substring(1), out k100)) k = k100 / 100f;
                    }
                    condition = parts[2].ToLowerInvariant().Contains("weighted")
                        ? CrowdingDecimationCondition.WeightedCrowding
                        : CrowdingDecimationCondition.Uniform;
                }
            }
            catch (Exception)
            {
                fixationIndex = 0;
                k = 1f;
                condition = CrowdingDecimationCondition.Uniform;
            }
        }
    }
}
